contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set a non-maintainer address
        address nonMaintainer = address(0x123);

        // Prank as non-maintainer and call adjustMtFeeRate; reference reverts, bug may not
        bool ok = true;
        vm.prank(nonMaintainer);
        try c.adjustMtFeeRate(1e18) { ok = true; } catch { ok = false; }
        assertTrue(ok == false); // reference reverts, buggy version might not if onlyMaintainer missing
